<template>
  <div class="space-y-6">
    <PageHeader :title="editingId ? '编辑代理链' : '创建代理链'" parent="代理" description="选择两到三个节点与每一跳的中转出站。服务器校验协议能力、内部凭据和专用入站后保存。"><template #actions><router-link to="/proxy/chains" class="ios-btn-secondary">返回代理链</router-link></template></PageHeader>
    <ErrorState v-if="error" :message="error" @retry="load" /><LoadingSkeleton v-else-if="loading" />
    <form v-else @submit.prevent="save" class="space-y-6">
      <section class="panel-card p-6 space-y-4"><h2 class="font-semibold">基础信息</h2><label class="block text-sm">名称<input v-model="form.name" maxlength="120" required class="form-input-base mt-2" /></label><div class="flex gap-4 text-sm"><label><input v-model="form.enabled" type="checkbox" /> 启用</label><label><input v-model="form.supportTcp" type="checkbox" /> TCP</label><label><input v-model="form.supportUdp" type="checkbox" /> UDP</label></div></section>
      <section class="panel-card p-6 space-y-4"><h2 class="font-semibold">节点与每跳出站</h2><p class="text-xs text-gray-500">每跳需先在目标节点创建内部入站，再在来源节点创建对应出站。代理链要求该内部入站只绑定这一条中转出站。</p>
        <div v-for="(id, index) in form.nodeIds" :key="index" class="border border-gray-100 rounded-xl p-4 space-y-3">
          <label class="block text-sm">{{ index === 0 ? '入口节点' : index === form.nodeIds.length - 1 ? '出口节点' : '中转节点' }}<select v-model="form.nodeIds[index]" required @change="nodeChanged" class="form-input-base mt-2"><option value="">请选择</option><option v-for="node in nodes.filter(item => item.enabled)" :key="node.id" :value="node.id">{{ node.name }}</option></select></label>
          <label v-if="index < form.nodeIds.length - 1" class="block text-sm">到下一节点的出站<select v-model="form.outboundIds[index]" required class="form-input-base mt-2"><option value="">请选择</option><option v-for="outbound in hopOptions(index)" :key="outbound.id" :value="outbound.id">{{ outbound.name }} · {{ outbound.protocol }} · {{ outbound.supportTcp ? 'TCP' : '' }} {{ outbound.supportUdp ? 'UDP' : '' }}</option></select></label>
          <p v-if="index < form.nodeIds.length - 1 && !hopOptions(index).length" class="text-xs text-amber-700">尚无符合来源、目标和 TCP/UDP 要求的中转出站。</p>
        </div>
        <button v-if="form.nodeIds.length === 2" type="button" @click="addMiddle" class="ios-btn-secondary">增加中转节点</button><button v-else type="button" @click="removeMiddle" class="ios-btn-secondary">移除中转节点</button>
        <label class="block text-sm">最终出站<select v-model="form.finalOutboundId" required class="form-input-base mt-2"><option value="direct">Direct</option><option value="block">Block</option><option v-for="outbound in finalOptions" :key="outbound.id" :value="outbound.id">{{ outbound.name }} · {{ outbound.protocol }}</option></select></label>
      </section>
      <section class="panel-card p-6 space-y-4"><h2 class="font-semibold">失败处理</h2><label class="block text-sm">链路不可用时<select v-model="form.failurePolicy" class="form-input-base mt-2"><option value="Block">阻断</option><option value="Direct">从入口直连</option><option value="BackupOutbound">入口备用出站</option><option value="BackupProxyChain">备用代理链</option><option value="BackupOutboundGroup">备用出口组</option></select></label>
        <label v-if="form.failurePolicy === 'BackupOutbound'" class="block text-sm">入口备用出站<select v-model="form.backupTargetId" class="form-input-base mt-2"><option value="">请选择</option><option v-for="outbound in backupOutbounds" :key="outbound.id" :value="outbound.id">{{ outbound.name }}</option></select></label>
        <label v-if="form.failurePolicy === 'BackupProxyChain'" class="block text-sm">备用代理链<select v-model="form.backupTargetId" class="form-input-base mt-2"><option value="">请选择</option><option v-for="chain in backupChains" :key="chain.id" :value="chain.id">{{ chain.name }}</option></select></label>
        <p v-if="form.failurePolicy === 'Direct'" class="text-xs text-amber-700">失败时从入口节点直接访问；要求固定出口的网站建议使用阻断或备用出口。</p>
      <label v-if="form.failurePolicy === 'BackupOutboundGroup'" class="block text-sm">备用出口组<select v-model="form.backupTargetId" class="form-input-base mt-2"><option value="">请选择</option><option v-for="group in groups.filter(item => item.enabled && item.nodeId === form.nodeIds[0])" :key="group.id" :value="group.id">{{ group.name }}</option></select></label></section>
      <section class="panel-card p-6"><h2 class="font-semibold mb-3">配置路径与校验</h2><p class="text-sm">{{ form.nodeIds.map(nodeName).join(' → ') }} → {{ finalName }}</p><ul v-if="problems.length" class="mt-3 space-y-1 text-sm text-amber-700"><li v-for="problem in problems" :key="problem">{{ problem }}</li></ul><p v-else class="mt-3 text-sm text-green-700">本地结构检查通过；保存时继续校验服务器协议能力、端口和独立绑定。</p><p class="text-xs text-gray-500 mt-3">路径来自草稿，不能代替连通性测试。保存后可在代理链列表创建发布批次。</p></section>
      <div class="flex justify-end gap-3"><router-link to="/proxy/chains" class="ios-btn-secondary">取消</router-link><button :disabled="saving || problems.length > 0" class="ios-btn-primary disabled:opacity-40">{{ saving ? '保存中…' : '保存代理链草稿' }}</button></div>
    </form>
  </div>
</template>
<script setup lang="ts">
import { ref, reactive, computed, onMounted } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { proxyAPI, choices, type ChainInput, type ProxyChain, type Outbound, type OutboundGroup } from '../api'; import { request, type Page } from '../../../app/apiClient'; import { type NodeView } from '../../nodes/api'; import { showToast } from '../../../app/api'; import PageHeader from '../../../components/PageHeader.vue'; import ErrorState from '../../../components/ErrorState.vue'; import LoadingSkeleton from '../../../components/LoadingSkeleton.vue';
const groups = ref<OutboundGroup[]>([]); const route = useRoute(); const router = useRouter(); const editingId = computed(() => typeof route.params.id === 'string' ? route.params.id : ''); const nodes = ref<NodeView[]>([]); const outbounds = ref<Outbound[]>([]); const chains = ref<ProxyChain[]>([]); const loading = ref(false); const saving = ref(false); const error = ref('');
const form = reactive<ChainInput>({ name: '', nodeIds: ['', ''], outboundIds: [''], finalOutboundId: 'direct', supportTcp: true, supportUdp: false, enabled: true, failurePolicy: 'Block', backupTargetId: '' });
function capable(outbound: Outbound) { return outbound.enabled && (!form.supportTcp || outbound.supportTcp) && (!form.supportUdp || outbound.supportUdp); }
function hopOptions(index: number) { return outbounds.value.filter(outbound => capable(outbound) && outbound.nodeId === form.nodeIds[index] && outbound.targetNodeId === form.nodeIds[index + 1] && !!outbound.targetInboundId); }
const finalOptions = computed(() => outbounds.value.filter(outbound => capable(outbound) && !outbound.targetNodeId && outbound.nodeId === form.nodeIds[form.nodeIds.length - 1]));
const backupOutbounds = computed(() => outbounds.value.filter(outbound => capable(outbound) && outbound.nodeId === form.nodeIds[0]));
const backupChains = computed(() => chains.value.filter(chain => chain.enabled && chain.id !== editingId.value && chain.nodeIds[0] === form.nodeIds[0] && (!form.supportTcp || chain.supportTcp) && (!form.supportUdp || chain.supportUdp)));
const finalName = computed(() => form.finalOutboundId === 'direct' ? 'Direct' : form.finalOutboundId === 'block' ? 'Block' : outbounds.value.find(item => item.id === form.finalOutboundId)?.name || form.finalOutboundId);
function nodeName(id: string) { return nodes.value.find(node => node.id === id)?.name || '未选择'; }
const problems = computed(() => { const result: string[] = []; if (form.nodeIds.some(id => !id)) result.push('请选择所有节点。'); if (form.nodeIds.filter(Boolean).length !== new Set(form.nodeIds.filter(Boolean)).size) result.push('节点不能重复或形成环路。'); if (!form.supportTcp && !form.supportUdp) result.push('至少选择 TCP 或 UDP。'); for (let index = 0; index < form.outboundIds.length; index++) if (!hopOptions(index).some(outbound => outbound.id === form.outboundIds[index])) result.push('请选择第 ' + (index + 1) + ' 跳的有效出站。'); if (form.failurePolicy.startsWith('Backup') && !form.backupTargetId) result.push('请选择备用目标。'); return result; });
function nodeChanged() { form.outboundIds = form.outboundIds.map((id,index) => hopOptions(index).some(item => item.id === id) ? id : ''); form.finalOutboundId = 'direct'; form.backupTargetId = ''; }
function addMiddle() { form.nodeIds.splice(1, 0, ''); form.outboundIds = ['', '']; }
function removeMiddle() { form.nodeIds.splice(1, 1); form.outboundIds = ['']; nodeChanged(); }
async function load() { loading.value = true; try { const [ns, outs, cs, gs] = await Promise.all([choices((p,s) => request<Page<NodeView>>('/nodes?page=' + p + '&pageSize=' + s)), choices((p,s) => proxyAPI.outbounds('',p,s)), choices((p,s) => proxyAPI.chains('',p,s)), choices((p,s) => proxyAPI.groups('',p,s))]); nodes.value = ns; outbounds.value = outs; chains.value = cs; groups.value = gs; if (editingId.value) { const chain = await proxyAPI.chain(editingId.value); Object.assign(form, { name: chain.name, nodeIds: [...chain.nodeIds], outboundIds: [...chain.outboundIds], finalOutboundId: chain.finalOutboundId, supportTcp: chain.supportTcp, supportUdp: chain.supportUdp, enabled: chain.enabled, failurePolicy: chain.failurePolicy === 'BackupChain' ? 'BackupProxyChain' : chain.failurePolicy, backupTargetId: chain.backupTargetId }); } error.value = ''; } catch (e) { error.value = (e as Error).message; } finally { loading.value = false; } }
async function save() { if (saving.value || problems.value.length) return; saving.value = true; try { await proxyAPI.saveChain(editingId.value || null, { ...form, nodeIds: [...form.nodeIds], outboundIds: [...form.outboundIds], backupTargetId: form.failurePolicy.startsWith('Backup') ? form.backupTargetId : '' }); showToast('代理链草稿已保存，请创建并发布批次'); await router.push('/proxy/chains'); } catch (e) { showToast((e as Error).message, 'error'); } finally { saving.value = false; } }
onMounted(load);
</script>
